// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // fuzz the 4-byte selector that will be forwarded as calldata
    function testFuzz_property(bytes4 sel) public {
        // We will deploy a helper that sometimes succeeds and sometimes reverts depending on selector.
        // Use two helpers so we can exercise both outcomes under control.
        CalleeMixed okCallee = new CalleeMixed(false);
        CalleeMixed reverter = new CalleeMixed(true);

        // Build calldata using the fuzzed selector and no args
        bytes memory data = abi.encodeWithSelector(sel);

        // 1) When the callee will revert on any call, the reference forwards and causes the low-level call to fail -> c.forward should revert (i.e., outer call returns false in try/catch)
        // 2) When the callee succeeds, the reference returns normally; the mutant would revert in that case.
        // We assert the universal property that: for ANY selector, calling forward to the succeeding callee returns (does not revert).
        // This is true for the reference for all sel; the mutant will fail for some sel (the fuzzer will find one where the helper succeeds and mutant reverts).

        bool ok;
        // call the succeeding callee (should not revert on reference for ANY sel)
        try c.forward(address(okCallee), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // The single assertion: reference should never revert when calling a callee that is designed to succeed.
        // We ensure okCallee is in "succeed" mode by construction (false => do not revert).
        assertTrue(ok);
    }
}

// Helper that either reverts on any call (when shouldRevert==true) or records and succeeds (when false).
contract CalleeMixed {
    bool public shouldRevert;
    bytes public lastData;
    uint public calls;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    fallback() external payable {
        calls += 1;
        lastData = msg.data;
        if (shouldRevert) revert("revert");
        // succeed otherwise
    }
}
